import { Component, Inject, Prop, Vue } from 'vue-property-decorator';
import ButtonIcon from '../button-icon/index.vue';

@Component({
    components: { ButtonIcon }
})
export default class InputRow extends Vue {
    @Prop()
    public readonly fieldname: string;

    @Prop()
    public readonly label: string;

    @Prop()
    public readonly selectText?: string;

    @Prop()
    public readonly fieldHelp: string;

    @Prop()
    public readonly options: object;

    @Prop()
    public readonly errors: string[];

    @Prop()
    public readonly value: number;

    @Prop()
    public readonly readonly: boolean;

    @Inject()
    public readonly errorText: string;

    @Inject()
    public readonly helpText: string;

    public onInput(event: Event): void {
        this.$emit('input', parseInt((event.target as HTMLSelectElement).value, 10));
        this.$nextTick(this.validateField);
    }

    public onHelpClicked(): void {
        this.$emit('update-help-text', this.fieldHelp);
    }

    public validateField(): boolean {
        const valid = !(this.value < 0);
        this.$emit('field-validation', this.fieldname, valid);
        return valid;
    }
}